// frontend/src/pages/InstitutionDashboard.js
import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import axios from 'axios';

export default function InstitutionDashboard() {
  const { user, apiBase } = useAuth();
  const [institution, setInstitution] = useState(null);
  const [faculties, setFaculties] = useState([]);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);

  // forms
  const [facultyName, setFacultyName] = useState('');
  const [facultyDesc, setFacultyDesc] = useState('');
  const [courseName, setCourseName] = useState('');
  const [courseDesc, setCourseDesc] = useState('');
  const [courseFacultyId, setCourseFacultyId] = useState('');

  useEffect(() => {
    if (!user) return;
    const fetchData = async () => {
      setLoading(true);
      try {
        // Get institution profile (public route by id)
        const res = await axios.get(`${apiBase}/institutions/${user.uid}`);
        setInstitution(res.data.institution);
        setFaculties(res.data.faculties || []);
        setCourses(res.data.courses || []);
      } catch (err) {
        console.error('Error fetching institution data', err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user, apiBase]);

  const addFaculty = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`${apiBase}/institutions/${user.uid}/faculties`, {
        name: facultyName,
        description: facultyDesc
      });
      // reload faculties
      const res = await axios.get(`${apiBase}/institutions/${user.uid}`);
      setFaculties(res.data.faculties || []);
      setFacultyName('');
      setFacultyDesc('');
    } catch (err) {
      console.error('Add faculty error', err);
      alert(err?.response?.data?.error || 'Failed to add faculty');
    }
  };

  const addCourse = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`${apiBase}/institutions/${user.uid}/courses`, {
        facultyId: courseFacultyId,
        name: courseName,
        description: courseDesc,
        duration: '3 years',
        fees: 0,
        seats: 50
      });
      const res = await axios.get(`${apiBase}/institutions/${user.uid}`);
      setCourses(res.data.courses || []);
      setCourseName('');
      setCourseDesc('');
    } catch (err) {
      console.error('Add course error', err);
      alert(err?.response?.data?.error || 'Failed to add course');
    }
  };

  if (!user) return <div>Please login as an institution to use this dashboard.</div>;
  if (loading) return <div>Loading dashboard...</div>;

  return (
    <div style={{ maxWidth: 900, margin: '0 auto' }}>
      <h2>Institution Dashboard</h2>
      <div>
        <strong>{institution?.name || 'Your Institution'}</strong>
        <div>{institution?.email}</div>
      </div>

      <hr/>

      <section>
        <h3>Faculties</h3>
        <ul>
          {faculties.map(f => <li key={f.id}>{f.name} - {f.description}</li>)}
        </ul>

        <form onSubmit={addFaculty} style={{ marginTop: 12 }}>
          <h4>Add Faculty</h4>
          <input placeholder="Faculty name" value={facultyName} onChange={e => setFacultyName(e.target.value)} required />
          <br/>
          <textarea placeholder="Description" value={facultyDesc} onChange={e => setFacultyDesc(e.target.value)} />
          <br/>
          <button type="submit">Add Faculty</button>
        </form>
      </section>

      <hr/>

      <section>
        <h3>Courses</h3>
        <ul>
          {courses.map(c => <li key={c.id}>{c.name} ({c.id}) - Faculty: {c.facultyId}</li>)}
        </ul>

        <form onSubmit={addCourse} style={{ marginTop: 12 }}>
          <h4>Add Course</h4>
          <select value={courseFacultyId} onChange={e => setCourseFacultyId(e.target.value)} required>
            <option value="">Select faculty</option>
            {faculties.map(f => <option value={f.id} key={f.id}>{f.name}</option>)}
          </select>
          <br/>
          <input placeholder="Course name" value={courseName} onChange={e => setCourseName(e.target.value)} required />
          <br/>
          <textarea placeholder="Course description" value={courseDesc} onChange={e => setCourseDesc(e.target.value)} />
          <br/>
          <button type="submit">Add Course</button>
        </form>
      </section>
    </div>
  );
}
